/* Stoic Ranger - Daily Thoughts — service worker of the web app (iPhone / iPad). Generated by tools/make-web.sh:
   VERSION and FILES are filled in at build time. Keeps every file of the app on the device, so it works offline;
   a new version replaces the cache in one go. Favourites live in the page's storage, never in this cache. */
const VERSION = '__VERSION__';
const FILES = __FILES__;
const CACHE = 'sr-daily-thoughts-' + VERSION;
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES.map(f => new Request(f, { cache: 'reload' })))).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k.startsWith('sr-daily-thoughts-') && k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  const u = new URL(e.request.url);
  if (u.origin !== location.origin) return;
  e.respondWith(caches.open(CACHE).then(c => c.match(e.request, { ignoreSearch: true }).then(hit => hit ||
    (u.pathname.endsWith('/') ? c.match('index.html') : null)).then(hit => hit || fetch(e.request))));
});
